import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Info } from '../types'

const empty: Info = {
  model: '',
  effort: '',
  dir: '',
  branch: '',
  mode: '',
  tokens: 0,
  window: 0,
  percent: 0,
  compactAt: 0,
}

const info = atom({ plugin: 'context-bar', key: 'info' } as const, empty)
// Which menu is open above the bar, if any.
const menu = atom({ plugin: 'context-bar', key: 'menu' } as const, null)

function short(n: number): string {
  if (n >= 1_000_000) {
    return `${(n / 1_000_000).toFixed(1).replace(/\.0$/, '')}M`
  }

  return n >= 1000 ? `${Math.round(n / 1000)}k` : `${n}`
}

function modelName(id: string): string {
  const name = (family: string, major: string, minor?: string) =>
    `${family[0].toUpperCase()}${family.slice(1)} ${major}${minor ? `.${minor}` : ''}`
  const current = id.match(/claude-(opus|sonnet|haiku|fable)-(\d+)(?:-(\d{1,2})(?!\d))?/)

  if (current) {
    return name(current[1], current[2], current[3])
  }

  const legacy = id.match(/claude-(\d+)(?:-(\d{1,2})(?!\d))?-(opus|sonnet|haiku)/)

  return legacy ? name(legacy[3], legacy[1], legacy[2]) : id
}

function tail(path: string): string {
  return path.split('/').filter(Boolean).slice(-2).join('/') || path
}

// Yellow from 50 percent, red at the compact threshold (85 percent when none is set).
function levelColor(percent: number, compactAt: number): string {
  return percent >= (compactAt > 0 ? compactAt : 85) ? 'red' : percent >= 50 ? 'yellow' : 'white'
}

// The bar as runs of one look each: the fill, the head, the rest, and the compact line.
type Run = { kind: 'fill' | 'head' | 'rest' | 'line'; text: string }

function runs(length: number, head: number, line: number | null): Run[] {
  const out: Run[] = []

  for (let n = 0; n < length; n++) {
    const kind = n === line ? 'line' : n < head ? 'fill' : n === head ? 'head' : 'rest'
    const text = kind === 'line' ? '┃' : kind === 'fill' ? '━' : kind === 'head' ? '●' : '─'
    const last = out[out.length - 1]

    if (last && last.kind === kind && kind !== 'line') {
      last.text += text
    } else {
      out.push({ kind, text })
    }
  }

  return out
}

const modeLabels: Record<string, string> = {
  acceptEdits: 'accept edits',
  plan: 'plan',
  bypassPermissions: 'bypass',
  dontAsk: 'dont ask',
  auto: 'auto',
}

type Live = Pick<Info, 'model' | 'effort' | 'mode'>

const LEVELS = ['low', 'medium', 'high', 'xhigh', 'max']

// The `/model` family aliases. The engine maps each to the newest model of its family,
// so the menu follows new releases when Claude Code updates. Pinned model IDs would not.
const MODELS = [
  { label: 'Fable', alias: 'fable' },
  { label: 'Opus', alias: 'opus' },
  { label: 'Sonnet', alias: 'sonnet' },
  { label: 'Haiku', alias: 'haiku' },
]

// The level the person cycled to, kept until the settings change under it.
let pressed: { level: string; baseline: string } | null = null

function effortOf(model: string, settings: Record<string, unknown>): string {
  const perModel = settings.modelSettings as Record<string, { effortLevel?: string }> | undefined
  const override = Object.entries(perModel ?? {}).find(([id]) => model.includes(id))?.[1]

  return String(override?.effortLevel ?? settings.effortLevel ?? '')
}

async function live($: EngineInterface): Promise<Live> {
  const [model, rows, settings] = await Promise.all([
    $.session.model(),
    $.config.list(),
    $.settings.read(),
  ])
  const mode = rows.find(row => row.key === 'permissionMode')?.value
  const fromSettings = effortOf(model, settings)

  if (pressed && pressed.baseline !== fromSettings) {
    pressed = null
  }

  return {
    model: modelName(model),
    effort: pressed?.level ?? fromSettings,
    mode: modeLabels[String(mode)] ?? '',
  }
}

// Runs `/effort` with the chosen level, shows it at once, and closes the menu.
async function setEffort($: EngineInterface, level: string) {
  const [model, settings] = await Promise.all([$.session.model(), $.settings.read()])

  await update($, menu, () => null)
  await $.command.run({ command: 'effort', args: level })
  pressed = { level, baseline: effortOf(model, settings) }
  await update($, info, i => ({ ...i, effort: level }))
  $.ui.toast(`Effort: ${level}`)
}

// Runs `/model` with the chosen alias, then checks that the session took it.
async function setModel($: EngineInterface, choice: { label: string; alias: string }) {
  const before = await $.session.model()

  await update($, menu, () => null)
  await $.command.run({ command: 'model', args: choice.alias })

  const after = await $.session.model()

  pressed = null
  await sync($)
  $.ui.toast(after === before ? `Could not switch to ${choice.label}` : `Model: ${modelName(after)}`)
}

// The percent of the window where auto-compact starts, from the settings that name it.
async function compactPercent($: EngineInterface, window: number): Promise<number> {
  const [percent, tokens] = await Promise.all([
    $.env.get('CLAUDE_AUTOCOMPACT_PCT_OVERRIDE'),
    $.env.get('CLAUDE_CODE_AUTO_COMPACT_WINDOW'),
  ])
  const fromPercent = Number.parseFloat(percent ?? '')
  const fromTokens = Number.parseFloat(tokens ?? '')

  if (fromPercent > 0 && fromPercent <= 100) {
    return Math.round(fromPercent)
  }

  return fromTokens > 0 && window > 0 ? Math.min(100, Math.round((fromTokens / window) * 100)) : 0
}

async function refresh($: EngineInterface) {
  const [usage, cwd, now] = await Promise.all([$.session.usage(), $.session.cwd(), live($)])
  const git = await $.process.run(['git', 'rev-parse', '--abbrev-ref', 'HEAD'], { cwd })
  const next: Info = {
    ...now,
    dir: tail(cwd),
    branch: git.exitCode === 0 ? git.stdout.trim() : '',
    tokens: usage.context.tokens ?? 0,
    window: usage.context.window,
    percent: usage.context.percent ?? 0,
    compactAt: await compactPercent($, usage.context.window),
  }
  await update($, info, () => next)
}

async function sync($: EngineInterface) {
  const [now, current] = await Promise.all([live($), read($, info)])

  if (now.model !== current.model || now.effort !== current.effort || now.mode !== current.mode) {
    await update($, info, i => ({ ...i, ...now }))
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await refresh($)
    $.clock.every(1000, () => sync($))

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    await refresh($)

    return result
  })

  on('ui.render', { component: 'PromptHint' }, ($, e) => {
    const { Box } = $.ui.resolve(e)

    return <Box />
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const [i, open] = await Promise.all([read($, info), read($, menu)])

    if (e.props.hasSurvey || i.window === 0) {
      return next(e)
    }

    const below = await next(e)
    const { Box, Button, Text } = $.ui.resolve(e)
    const color = levelColor(i.percent, i.compactAt)
    const left = [i.model, i.effort, i.dir, i.branch, i.mode].filter(Boolean)
    const leftLength = left.reduce((n, s) => n + s.length + 3, 0)
    const percent = ` ${i.percent}% `
    const sizes = ` ${short(i.tokens)}/${short(i.window)}${i.compactAt > 0 ? ` compact ${i.compactAt}%` : ''}`
    const barLength = Math.max(8, e.props.bodyColumns - leftLength - percent.length - sizes.length - 5)
    const head = Math.min(barLength - 1, Math.round((i.percent / 100) * (barLength - 1)))
    const line = i.compactAt > 0 ? Math.min(barLength - 1, Math.round((i.compactAt / 100) * (barLength - 1))) : null

    return (
      <Box flexDirection="column">
      {open === 'model' ? (
        <Box marginLeft={1} flexDirection="column" borderStyle="round" borderColor="gray" alignSelf="flex-start">
          {MODELS.map(choice => (
            <Button
              key={`model-${choice.alias}`}
              plain
              dimColor={!i.model.toLowerCase().startsWith(choice.label.toLowerCase())}
              label={`${i.model.toLowerCase().startsWith(choice.label.toLowerCase()) ? '●' : ' '} ${choice.label}`}
              onPress={() => setModel($, choice)}
            />
          ))}
        </Box>
      ) : null}
      {open === 'effort' ? (
        <Box marginLeft={i.model.length + 6} flexDirection="column" borderStyle="round" borderColor="gray" alignSelf="flex-start">
          {[...LEVELS].reverse().map(level => (
            <Button
              key={`level-${level}`}
              plain
              dimColor={level !== i.effort}
              label={`${level === i.effort ? '●' : ' '} ${level}`}
              onPress={() => setEffort($, level)}
            />
          ))}
        </Box>
      ) : null}
      <Box>
        {left.map((s, n) =>
          n === 0 ? (
            <Box key={n}>
              <Text dimColor>{'▶ '}</Text>
              <Button key="model" plain label={open === 'model' ? `${s} ▾` : `${s} ▴`} onPress={() => update($, menu, now => (now === 'model' ? null : 'model'))} />
              <Text>{' '}</Text>
            </Box>
          ) : s === i.effort ? (
            <Box key={n}>
              <Text dimColor>{'▶ '}</Text>
              <Button key="effort" plain dimColor label={open === 'effort' ? `${s} ▾` : `${s} ▴`} onPress={() => update($, menu, now => (now === 'effort' ? null : 'effort'))} />
              <Text>{' '}</Text>
            </Box>
          ) : (
            <Text key={n}>
              <Text dimColor>{'▶ '}</Text>
              <Text bold={n === 0} color={n === left.length - 1 && i.mode ? 'yellow' : undefined}>{s}</Text>
              <Text>{' '}</Text>
            </Text>
          ),
        )}
        <Text color={color} bold>{percent}</Text>
        {runs(barLength, head, line).map((run, n) => (
          <Text key={n} color={run.kind === 'line' ? 'cyan' : run.kind === 'rest' ? undefined : color} dimColor={run.kind === 'rest'} bold={run.kind === 'line'}>
            {run.text}
          </Text>
        ))}
        <Text dimColor>{sizes}</Text>
      </Box>
        {below ?? null}
      </Box>
    )
  })
}

