export type Info = {
  model: string
  effort: string
  dir: string
  branch: string
  mode: string
  tokens: number
  window: number
  percent: number
  // The percent of the window where auto-compact starts; 0 when no setting names it.
  compactAt: number
}

declare module 'claude-code' {
  interface PluginState {
    'context-bar': { info: Info; menu: 'effort' | 'model' | null }
  }
}
